"""Address hints for the unresolved queue, never a substitute for coordinates."""
import re
NEARBY=('казань','татарстан','зеленодольск','иннополис','волжск','лаишево','арск','высокая гора','высокогор','пестрецы','пестреч','верхний услон','верхнеуслон','нижние вязовые','васильево','осиново','столбище','усады','сокуры','кощаково','новый кинер','балтаси','богатые сабы','тюлячи','каменское устье','рыбная слобода','алексеевское','апастово','атня','юрмолинка','юрма','айша','бело-безводное','большие кабаны','малые кабаны','борисоглебское','салмачи','кующи','кулаево','константиновка','киндери','кульсеитово','нагорный','чебакса','царево','счастливый','новое шигалеево')
def candidate(row):
    address=(row.get('address') or '').casefold().replace('ё','е')
    return any(re.search(r'(?<!\w)'+re.escape(t),address) for t in NEARBY)
